fields.InputDefinition:
{
  "goal": "Open the 'Members' entity grid — type 'Members' in the LEFT sidebar 'Search entities...' box and click the EXACT 'Members' match (or navigate to http://localhost:4200/app/data-explorer/Data?entity=Members). Click the 'New Record' (New/Create) button to open a blank Member form. WITHOUT filling the required fields (those marked with a red asterisk *), click Save. Verify the app responds with a clear VALIDATION message indicating required field(s) are missing (e.g. a field-level error or a 'required' message) and does NOT crash, show a blank screen, or save an invalid record. Reaching that validation-blocked state is success. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "A new record form was opened and Save attempted with required field(s) empty",
    "The app surfaced a clear validation/required-field message and blocked the invalid save",
    "No crash, blank screen, or raw server error — handled gracefully"
  ]
}
